$ErrorActionPreference='Stop'
$j=Join-Path $env:TEMP ('smiot-auto-recovery-' + [guid]::NewGuid().ToString('N') + '.json')
$cmds=@('set -e','cd /opt/smiot','export PYTHONPATH=/opt/smiot','/opt/smiot/.venv/bin/python /opt/smiot/scripts/run_correlated_w3_w5.py --case W3')
(@{commands=$cmds}|ConvertTo-Json -Compress)|Set-Content -Encoding ascii $j
$id=(aws ssm send-command --profile aws-moi --region ap-southeast-2 --instance-ids i-00bf2d3591d3ee0a2 --document-name AWS-RunShellScript --parameters file://$j --comment 'SMIOT automatic scenario recovery test' --query Command.CommandId --output text).Trim(); do {Start-Sleep 3;$r=aws ssm get-command-invocation --profile aws-moi --region ap-southeast-2 --command-id $id --instance-id i-00bf2d3591d3ee0a2 --output json|ConvertFrom-Json;if($r.Status -in @('Success','Failed','Cancelled','TimedOut')){Write-Output $r.StandardOutputContent;if($r.Status -ne 'Success'){Write-Output $r.StandardErrorContent};break}}while($true); Remove-Item $j -Force -ErrorAction SilentlyContinue
